import{_ as s,C as o,o as n,c as i,a2 as t,E as a}from"./chunks/framework.BSaF8iZ6.js";const f=JSON.parse('{"title":"Shipments & Carriers","description":"","frontmatter":{},"headers":[],"relativePath":"orders/fulfilment-carriers.md","filePath":"orders/fulfilment-carriers.md","lastUpdated":1789411447000}'),h={name:"orders/fulfilment-carriers.md"};function l(d,e,c,u,g,p){const r=o("ImagePopup");return n(),i("div",null,[e[0]||(e[0]=t('<h1 id="shipments-carriers" tabindex="-1">Shipments &amp; Carriers <a class="header-anchor" href="#shipments-carriers" aria-label="Permalink to &quot;Shipments &amp; Carriers&quot;">​</a></h1><div class="page-roles"><span class="role role--seller">Seller</span><span class="role role--admin">Admin</span></div><p>Sellers ship their products by scheduling a pickup for the order. The carrier decides how the parcel travels. <strong>Self Ship</strong> is always available: the seller arranges their own courier and enters the tracking number. A courier integration can also buy labels and book collections for the seller.</p><p>Carriers are only used after an order is placed. Customers still choose from the store&#39;s shipping methods at checkout.</p><h2 id="schedule-a-pickup" tabindex="-1">Schedule a pickup <a class="header-anchor" href="#schedule-a-pickup" aria-label="Permalink to &quot;Schedule a pickup&quot;">​</a></h2><ol><li>Go to <strong>Sales &gt;&gt; Orders</strong>.</li><li>Click <strong>Schedule Pickup</strong> on the order&#39;s row, or open the order and click <strong>Schedule Pickup</strong>.</li><li>Choose the <strong>Product Ordered Source</strong> your products ship from.</li><li>Under <strong>Items To Ship</strong>, enter how many of each product you are shipping from that source. <strong>Avail.</strong> shows the stock in the source.</li><li>Choose the <strong>Carrier</strong>. For Self Ship, this is <strong>Manual (Own Arrangement)</strong>, unless the store has renamed it.</li><li>For Self Ship, you can enter the <strong>Carrier Title</strong>, such as the courier&#39;s name, and the <strong>Tracking ID</strong>.</li><li>Click <strong>Schedule Pickup</strong>.</li></ol>',6)),a(r,{src:"/images/order-management/shipment-create.png",alt:"The Schedule Pickup page with Self Ship"}),e[1]||(e[1]=t('<p>You&#39;ll see <strong>Shipment created successfully</strong>. The order&#39;s <strong>Shipments</strong> tab shows the carrier, the tracking number and the inventory source.</p><table tabindex="0"><thead><tr><th>Message</th><th>What it means</th></tr></thead><tbody><tr><td><strong>This order has nothing left to ship</strong></td><td>Everything in your part of the order has shipped, or what&#39;s left is cancelled, refunded or has nothing to ship, such as a booking.</td></tr><tr><td><strong>Requested quantity is not available</strong></td><td>You entered more than is left to ship or than the source has in stock, or every quantity is 0.</td></tr><tr><td><strong>Shipment blocked for RMA quantity: …</strong></td><td>Shown beside a product when that much of its quantity is in a return request, whatever the request&#39;s status. That quantity can&#39;t be shipped.</td></tr></tbody></table><h2 id="with-a-courier-integration" tabindex="-1">With a courier integration <a class="header-anchor" href="#with-a-courier-integration" aria-label="Permalink to &quot;With a courier integration&quot;">​</a></h2><p>When the store has installed and set up a courier integration, choosing it adds more to the page:</p><ul><li><strong>Parcel</strong> — the <strong>Weight</strong>, in the store&#39;s weight unit, and the <strong>Length</strong>, <strong>Width</strong> and <strong>Height</strong> in centimetres. Each must be more than 0. A shipping label is bought when you schedule the pickup, and the tracking number is added for you.</li><li><strong>Collection</strong> — the <strong>Pickup Date</strong>, which can&#39;t be in the past, and either a <strong>Collection Round</strong> or the <strong>Ready At</strong> and <strong>Doors Close At</strong> times, with any <strong>Pickup Instructions</strong> for the driver, up to 500 characters.</li></ul><p>After scheduling:</p><ul><li>download the label with <strong>Download</strong> on the shipment, or <strong>Print Label</strong> on the order&#39;s row;</li><li>the shipment shows the pickup&#39;s confirmation and time window, and the <strong>Label Cost</strong>;</li><li>shipments from the same source for the same collection time share one pickup.</li></ul><p>The label cost is shown for your information and isn&#39;t taken from your payout.</p><p>If the courier rejects the collection window, nothing is saved; choose another time and try again. If the courier can&#39;t be booked for another reason, the shipment is still saved and marked <strong>Not Booked</strong>.</p><h2 id="for-the-admin" tabindex="-1">For the admin <a class="header-anchor" href="#for-the-admin" aria-label="Permalink to &quot;For the admin&quot;">​</a></h2><ul><li>Set up the carriers sellers can use in <a href="./../configuration/fulfilment-carriers">Fulfilment Carriers settings</a>.</li><li>When you ship a seller&#39;s products from <strong>Sales &gt;&gt; Orders</strong>, the store&#39;s own shipment form is used, and only the seller&#39;s inventory sources are offered.</li></ul><h2 id="settings-and-permissions" tabindex="-1">Settings and permissions <a class="header-anchor" href="#settings-and-permissions" aria-label="Permalink to &quot;Settings and permissions&quot;">​</a></h2><ul><li>Sellers see <strong>Schedule Pickup</strong> when <strong>Can Create Shipment</strong> is on in <a href="./../configuration/sellers">Sellers settings</a>.</li><li>Team members need <strong>Orders</strong> with <strong>Shipment</strong>.</li></ul>',13))])}const S=s(h,[["render",l]]);export{f as __pageData,S as default};
